template:
{
    "daemon": {
        "hostname": "{{ daemon_hostname }}",
        "port": {{ daemon_port }},
        "logging_level": "{{ daemon_logging_level }}",
        "listener": "{{ daemon_listener }}"
    },
    "pdus": {
        {% for pdu in pdus %}
        "{{ pdu.name }}": {
            {% if pdu.driver == 'localcmdline' %}
            "driver": "localcmdline",
            "cmd_on": "echo '{{ pdu.name }} %s on' >> /tmp/pdu",
            "cmd_off": "echo '{{ pdu.name }} %s off' >> /tmp/pdu"
            {% elif pdu.driver == 'acme' %}
            "driver": "acme"
            {% elif pdu.driver == 'apc9210' %}
            "driver": "apc9210"
            {% elif pdu.driver == 'apc7952' %}
            "driver": "apc7952",
            "telnetport": {{ pdu.port | default(5023) }}
            {% if pdu.retries is defined %}
            ,"retries": {{ pdu.retries }}
            {% endif %}
            {% elif pdu.driver == 'apc8959' %}
            "driver": "apc8959"
            {% elif pdu.driver == 'ubntmfi3port' %}
            "driver": "ubntmfi3port",
            "username": "{{ pdu.username | default('ubnt') }}",
            "password": "{{ pdu.password | default('ubnt') }}",
            "sshport": {{ pdu.port | default(22) }},
            "verify_hostkey": true
            {% elif pdu.driver == 'snmpv3' %}
            "driver": "snmpv3",
            "username": "{{ pdu.username }}",
            {% if pdu.password %}
            "authpassphrase": "{{ pdu.password }}",
            "privpassphrase": "{{ pdu.privpassphrase | default(pdu.password) }}",
            {% endif %}
            "mib": "{{ pdu.mib | default('PowerNet-MIB') }}",
            "controlpoint": "{{ pdu.controlpoint | default('sPDUOutletCtl') }}",
            "onsetting": "{{ pdu.onsetting | default('1') }}",
            "offsetting": {{ pdu.offsetting | default(2) }}
            {% elif pdu.driver == 'snmpv1' %}
            "driver": "snmpv1",
            "community": "{{ pdu.snmp_community | default('private') }}",
            "mib": "{{ pdu.mib | default('PowerNet-MIB') }}",
            "controlpoint": "{{ pdu.controlpoint | default('sPDUOutletCtl') }}",
            "onsetting": "{{ pdu.onsetting | default('1') }}",
            "offsetting": {{ pdu.offsetting | default(2) }}
            {% elif pdu.driver == 'ClewareUsbSwitch4' %}
            "driver": "ClewareUsbSwitch4",
            "serial": {{ pdu.serial | default(12345) }}
            {% elif pdu.driver == 'ClewareUsbSwitch8' %}
            "driver": "ClewareUsbSwitch8",
            "serial": {{ pdu.serial | default(4321) }}
            {% elif pdu.driver == 'intellinet' %}
            "driver": "intellinet",
            "username": "{{ pdu.username | default('admin') }}",
            "password": "{{ pdu.password | default('admin') }}",
            "port": {{ pdu.port | default(80) }}
            {% elif pdu.driver == 'EG-PMS' %}
            "driver": "EG-PMS",
            "device": "{{ pdu.device | default('aa:bb:cc:xx:yy') }}"
            {% elif pdu.driver == 'localcmdline' %}
            "driver": "localcmdline"
            {% elif pdu.driver == 'servertechpro2' %}
            "driver": "servertechpro2",
            "ip": "{{ pdu.host | default('192.168.10.4') }}",
            "protocol": "{{ pdu.protocol | default('https') }}",
            "insecure": {{ pdu.insecure | default(true) | lower }},
            "username": "{{ pdu.username | default('testuser') }}",
            "password": "{{ pdu.password | default('testuser') }}"
            {% elif pdu.driver == 'tplink' %}
            "driver": "tplink"
            {% elif pdu.driver == 'ip9850' %}
            "driver": "ip9850",
            "ip": "{{ pdu.host | default('192.168.1.5') }}",
            "username": "{{ pdu.username | default('testuser') }}",
            "password": "{{ pdu.password | default('testpass') }}"
            {% elif pdu.driver == 'esphome-http' %}
            "driver": "esphome-http",
            "username": "{{ pdu.username | default('admin') }}",
            "password": "{{ pdu.password | default('web') }}"
            {% elif pdu.driver == 'SERVO' %}
            "driver": "SERVO",
            "ip": "{{ pdu.host | default('0.0.0.0') }}",
            "port": "{{ pdu.port | default('9902') }}",
            "ctrls": "{{ pdu.ctrls | default('cold_reset') }}"
            {% elif pdu.driver == 'LindyIPowerClassic8' %}
            "driver": "LindyIPowerClassic8",
            "username": "{{ pdu.username | default('snmp') }}",
            "password": "{{ pdu.password | default('1234') }}"
            {% elif pdu.driver == 'devantech_eth008' %}
            "driver": "devantech_eth008",
            "ip": "{{ pdu.host | default('192.168.56.101') }}",
            "port": "{{ pdu.port | default('17494') }}",
            "password": "{{ pdu.password | default('password') }}",
            "logic": "{{ pdu.logic | default('NO') }}"
            {% else %}
            "driver": "{{ pdu.driver }}"
            {% endif %}
            {% if loop.last %}
        }
        {% else %}
        },
        {% endif %}
        {% endfor %}
    },
    "aliases": {
        {% for alias in aliases %}
        "{{ alias.name }}": {
            "hostname": "{{ alias.pdu_name }}",
            "port": {{ alias.outlet }}
        }{% if not loop.last %},{% endif %}
        {% endfor %}
    }
}
